"""Bundles the map page and its server into hooks/web-assets.ts, the strings the mod writes out.

Run after editing web/index.html or web/server.mjs:  python -I web/build-assets.py
"""
import json
import pathlib

root = pathlib.Path(__file__).resolve().parent.parent
page = (root / "web" / "index.html").read_text(encoding="utf-8")
server = (root / "web" / "server.mjs").read_text(encoding="utf-8")
out = (
    "// Generated by web/build-assets.py from web/index.html and web/server.mjs: edit those, then run it.\n"
    f"export const INDEX_HTML: string = {json.dumps(page, ensure_ascii=False)}\n"
    f"export const SERVER_JS: string = {json.dumps(server, ensure_ascii=False)}\n"
)
(root / "hooks" / "web-assets.ts").write_text(out, encoding="utf-8")
print(f"wrote hooks/web-assets.ts ({len(out)} chars)")
